#!/usr/bin/env bash
# Read-only Shopify snapshot (allocator app credentials): product A in full, product list, all orders. $1 = output file, $2 = optional product B gid.
OUT="$1"; PB="${2:-gid://shopify/Product/0}"; umask 077; H=$(mktemp)
( trap 'rm -f "$H"' EXIT
jq -n --arg id "$SHOPIFY_CLIENT_ID" --arg s "$SHOPIFY_CLIENT_SECRET" '{client_id:$id,client_secret:$s,grant_type:"client_credentials"}' | curl -sS -X POST -H 'Content-Type: application/json' --data-binary @- https://7r5csb-1j.myshopify.com/admin/oauth/access_token | jq -r '"X-Shopify-Access-Token: " + .access_token' > "$H"
PF='id title handle status vendor productType descriptionHtml publishedAt onlineStoreUrl createdAt updatedAt tags totalInventory tracksInventory templateSuffix metafields(first: 30) { nodes { namespace key type value } } variants(first: 5) { nodes { id title sku price compareAtPrice taxable inventoryPolicy inventoryQuantity barcode selectedOptions { name value } metafields(first: 10) { nodes { namespace key type value } } inventoryItem { id tracked requiresShipping measurement { weight { value unit } } } } } options { name values }'
Q="query(\$pb: ID!) { a: product(id: \"gid://shopify/Product/15897614614902\") { $PF } b: product(id: \$pb) { $PF } products(first: 100, sortKey: ID) { nodes { id title handle status updatedAt totalInventory } } orders(first: 100, sortKey: CREATED_AT) { nodes { id name createdAt updatedAt cancelledAt displayFinancialStatus displayFulfillmentStatus tags lineItems(first: 10) { nodes { id sku quantity currentQuantity product { id } } } } } }"
jq -n --arg q "$Q" --arg pb "$PB" '{query:$q, variables:{pb:$pb}}' | curl -sS -X POST -H @"$H" -H 'Content-Type: application/json' --data-binary @- https://7r5csb-1j.myshopify.com/admin/api/2026-07/graphql.json | jq -S '{errors:[.errors[]?.message], product_a:.data.a, product_b:.data.b, products:.data.products.nodes, orders:.data.orders.nodes}' > "$OUT" )
